import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

 @Test void rejectsInvalid(){assertThrows(RuntimeException.class,()->new ActivityHistory(0));assertThrows(RuntimeException.class,()->new ActivityHistory(257));assertThrows(RuntimeException.class,()->new ActivityHistory(1).append(null));}

 private ActivityEvent eventAt(Instant timestamp, ActivityEvent.Type type, Long quantity) {
  return new ActivityEvent(1, timestamp.toString(), type, List.of("minecraft:stone"), quantity, ActivityEvent.Source.MANUAL);
 }

 private void assertWindowSummary(ActivityWindow window, int count, long quantity,
                                  Map<ActivityEvent.Type, Integer> nonzeroCounts) {
  assertEquals(count, window.summary().eventCount());
  assertEquals(quantity, window.summary().totalQuantity());
  assertEquals(ActivityEvent.Type.values().length, window.summary().counts().size());
  for (var type : ActivityEvent.Type.values()) {
   assertEquals(nonzeroCounts.getOrDefault(type, 0), window.summary().counts().get(type), type.name());
  }
 }

 private void assertEmptyWindow(ActivityWindow window) {
  assertEquals(List.of(), window.events());
  assertWindowSummary(window, 0, 0L, Map.of());
 }

 @Test void betweenUsesHalfOpenBoundariesAndSummarizesOnlySelectedEvents() {
  var start = Instant.parse("2026-09-23T12:00:00Z");
  var end = start.plusSeconds(10);
  var before = eventAt(start.minusNanos(1), ActivityEvent.Type.ITEM_GAINED, 50L);
  var atStart = eventAt(start, ActivityEvent.Type.ITEM_GAINED, 2L);
  var inside = eventAt(start.plusSeconds(3), ActivityEvent.Type.ITEM_GAINED, 3L);
  var lost = eventAt(start.plusSeconds(5), ActivityEvent.Type.ITEM_LOST, 7L);
  var justInside = eventAt(end.minusNanos(1), ActivityEvent.Type.DIMENSION_CHANGED, null);
  var atEnd = eventAt(end, ActivityEvent.Type.ITEM_CRAFTED, 100L);
  var after = eventAt(end.plusNanos(1), ActivityEvent.Type.BLOCK_BROKEN, 200L);
  var original = List.of(before, atStart, inside, lost, justInside, atEnd, after);
  var history = new ActivityHistory(7);
  original.forEach(history::append);

  var window = history.between(start, end);

  assertEquals(List.of(atStart, inside, lost, justInside), window.events());
  assertWindowSummary(window, 4, 12L, Map.of(
      ActivityEvent.Type.ITEM_GAINED, 2,
      ActivityEvent.Type.ITEM_LOST, 1,
      ActivityEvent.Type.DIMENSION_CHANGED, 1));
  assertEquals(original, history.recent());
  assertEquals(7, history.size());
  assertEquals(window, history.between(start, end));
  assertEquals(original, history.recent());
  assertEquals(7, history.size());
 }

 @Test void betweenReturnsEmptySummariesForEmptyHistoryEqualEndpointsAndNoMatches() {
  var start = Instant.parse("2026-09-23T12:00:00Z");
  var history = new ActivityHistory(1);
  assertEmptyWindow(history.between(start, start.plusSeconds(1)));
  assertEmptyWindow(history.between(start, start));
  assertEquals(List.of(), history.recent());
  assertEquals(0, history.size());

  var event = eventAt(start, ActivityEvent.Type.ITEM_GAINED, 9L);
  history.append(event);
  assertEmptyWindow(history.between(start, start));
  assertEmptyWindow(history.between(start.plusNanos(1), start.plusSeconds(1)));
  assertEquals(List.of(event), history.recent());
  assertEquals(1, history.size());
 }

 @Test void betweenRejectsInvalidEndpointsWithoutChangingHistory() {
  var start = Instant.parse("2026-09-23T12:00:00Z");
  var populated = new ActivityHistory(1);
  populated.append(eventAt(start, ActivityEvent.Type.ITEM_GAINED, 1L));
  for (var history : List.of(new ActivityHistory(1), populated)) {
   var original = history.recent();
   assertThrows(IllegalArgumentException.class, () -> history.between(null, start));
   assertThrows(IllegalArgumentException.class, () -> history.between(start, null));
   assertThrows(IllegalArgumentException.class, () -> history.between(null, null));
   assertThrows(IllegalArgumentException.class, () -> history.between(start.plusNanos(1), start));
   assertEquals(original, history.recent());
   assertEquals(original.size(), history.size());
  }
 }

 @Test void betweenPreservesAppendOrderAndExcludesEvictedEvents() {
  var start = Instant.parse("2026-09-23T12:00:00Z");
  var end = start.plusSeconds(10);
  var evicted = eventAt(start.plusSeconds(4), ActivityEvent.Type.ITEM_CRAFTED, 100L);
  var later = eventAt(start.plusSeconds(8), ActivityEvent.Type.ITEM_GAINED, 2L);
  var outside = eventAt(end.plusSeconds(1), ActivityEvent.Type.BLOCK_BROKEN, 50L);
  var earlier = eventAt(start.plusSeconds(2), ActivityEvent.Type.ITEM_LOST, 3L);
  var history = new ActivityHistory(3);
  List.of(evicted, later, outside, earlier).forEach(history::append);

  var window = history.between(start, end);

  assertEquals(List.of(later, earlier), window.events());
  assertWindowSummary(window, 2, 5L, Map.of(
      ActivityEvent.Type.ITEM_GAINED, 1, ActivityEvent.Type.ITEM_LOST, 1));
  assertEquals(List.of(later, outside, earlier), history.recent());
  assertEquals(3, history.size());
 }

 @Test void returnedWindowIsImmutableAndSurvivesAppendEvictionAndClear() {
  var start = Instant.parse("2026-09-23T12:00:00Z");
  var end = start.plusSeconds(10);
  var first = eventAt(start, ActivityEvent.Type.ITEM_GAINED, 2L);
  var second = eventAt(start.plusSeconds(1), ActivityEvent.Type.ITEM_LOST, 3L);
  var replacement = eventAt(start.plusSeconds(2), ActivityEvent.Type.ITEM_CRAFTED, 20L);
  var history = new ActivityHistory(2);
  history.append(first);
  history.append(second);
  var window = history.between(start, end);
  var expectedEvents = List.of(first, second);
  var expectedCounts = Map.of(ActivityEvent.Type.ITEM_GAINED, 1, ActivityEvent.Type.ITEM_LOST, 1);

  assertThrows(UnsupportedOperationException.class, () -> window.events().clear());
  assertThrows(UnsupportedOperationException.class, () -> window.events().add(replacement));
  assertThrows(UnsupportedOperationException.class, () -> window.events().set(0, replacement));
  assertEquals(expectedEvents, history.recent());
  assertEquals(2, history.size());

  history.append(replacement);
  assertEquals(List.of(second, replacement), history.recent());
  assertEquals(expectedEvents, window.events());
  assertWindowSummary(window, 2, 5L, expectedCounts);

  history.clear();
  assertEquals(0, history.size());
  assertEmptyWindow(history.between(start, end));
  assertEquals(expectedEvents, window.events());
  assertWindowSummary(window, 2, 5L, expectedCounts);
 }

 @Test void activityWindowDefensivelyCopiesConstructorList() {
  var original = e("minecraft:stone");
  var replacement = e("minecraft:dirt");
  var suppliedEvents = new ArrayList<>(List.of(original));
  var window = new ActivityWindow(suppliedEvents, ActivitySummary.from(suppliedEvents));

  suppliedEvents.set(0, replacement);
  assertEquals(List.of(original), window.events());
  suppliedEvents.clear();
  suppliedEvents.add(replacement);
  assertEquals(List.of(original), window.events());
  assertWindowSummary(window, 1, 1L, Map.of(ActivityEvent.Type.ITEM_GAINED, 1));
  assertThrows(UnsupportedOperationException.class, () -> window.events().clear());
  assertThrows(UnsupportedOperationException.class, () -> window.events().add(replacement));
  assertThrows(UnsupportedOperationException.class, () -> window.events().set(0, replacement));
  assertEquals(List.of(original), window.events());
 }
}

